# area: typevartuple_unpack
# hypothesis: Generic[*Ts, P] with a defaulted ParamSpec after a TypeVarTuple may raise TypeError at runtime on CPython 3.13 while mypy and ty accept it and disagree on reveal types.
from typing import Callable, Generic, ParamSpec, TypeVarTuple, reveal_type

Ts = TypeVarTuple('Ts')
P = ParamSpec('P', default=[bool])


class Holder(Generic[*Ts]):
    def __init__(self, *items: *Ts) -> None:
        self.items = items


def make_generic_callback() -> str:
    try:
        class Callback(Generic[*Ts, P]):
            fn: Callable[P, tuple[*Ts]]
        reveal_type(Callback)
        return 'accepted'
    except TypeError:
        return 'TypeError'


def make_pep695_callback() -> str:
